sn_aia_tool.script:
(function(inputs) {

    gs.info("Inputs to replace badge scenario : ");
    gs.info("Old asset : " + JSON.stringify(inputs.old_asset));
    gs.info("id : " + inputs.identity_id);
    gs.info("VT : " + inputs.valid_till);

    var subflowInputs = {};
    // subflowInputs['web_prov'] = "false"; // String 
    // subflowInputs['location_sys_id'] = ; // String 
    subflowInputs['user_sys_id'] = ""; // String 
    subflowInputs['action_to_perform'] = "replace"; // String 
    subflowInputs['valid_from'] = new GlideDateTime().getDisplayValue(); // String 
    subflowInputs['valid_to'] = new GlideDateTime().getDisplayValue();; // String 
    subflowInputs['submission_mode'] = "direct"; // String 
    // subflowInputs['reason'] = ""; // String 
    // subflowInputs['assign_default_access'] = ""; // String 
    // subflowInputs['badge_id_assign'] = ; // String 
    subflowInputs['badge_id_to_replace'] = {}; // String 
    // subflowInputs['copy_access'] = ; // String 
    subflowInputs['deactivate_old_badge'] = "true"; // String 

    // Start Asynchronously: Uncomment to run in background. Code snippet will not have access to outputs.
    sn_fd.FlowAPI.getRunner().subflow('x_aleen_aia_skills.guardian_ai_agent_badge_assignment_subflow').inBackground().withInputs(subflowInputs).run();

    // Execute Synchronously: Run in foreground. Code snippet has access to outputs.
    // var result = sn_fd.FlowAPI.getRunner().subflow('x_aleen_aia_skills.guardian_ai_agent_badge_assignment_subflow').inForeground().withInputs(subflowInputs).run();
    // var outputs = result.getOutputs();
    // var response = outputs['response']; // String
    // return response;

    // Get Outputs:
    // Note: outputs can only be retrieved when executing synchronously.
})(inputs);
